const numeric=(v,p='',out=[])=>{if(typeof v==='number'&&Number.isFinite(v))out.push(p);else if(v&&typeof v==='object')for(const[k,x]of Object.entries(v))numeric(x,p?`${p}.${k}`:k,out);return out};
const numericStrings=(v,p='',out={})=>{if(typeof v==='string'&&/\d/.test(v))out[p]=v;else if(v&&typeof v==='object')for(const[k,x]of Object.entries(v))numericStrings(x,p?`${p}.${k}`:k,out);return out};
const fmt=(n,d=2)=>new Intl.NumberFormat('fr-FR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
