function facet(file,type){const r=read(file).data?.items?.[0]?.results||[];const row=r.find(x=>x.data_type===type);return row?.data?.[0]??{};}
function qfacet(file,type){const r=read(file).data?.items?.[0]?.results||[];return r.find(x=>x.data_type===type)?.data?.[0]??{};}
function closeBars(file,ticker){const raw=read(file);return normalizeBars({bars:raw.results[0].data[0].bars},ticker,EQUITY_CALENDAR);}
function returns(bars,n){return bars.length>n?(bars.at(-1).close/bars.at(-(n+1)).close-1)*100:null}
function oldClose(bars,date){return bars.find(x=>x.date===date)?.close}
function intervals(bars){let y=bars.find(x=>x.date==='2025-12-31')?.close;let ytd=y?(bars.at(-1).close/y-1)*100:null;let year=bars.find(x=>x.date==='2025-09-11')?.close;return{ytd,one:year?(bars.at(-1).close/year-1)*100:null};}
function getComparison(file){const rows=read(file).data?.items?.[0]?.results?.find(x=>x.data_type==='bars_daily')?.data||[];const out=new Map;for(const r of rows){const b=(r.bars||[]).map(x=>({date:x[0],close:Number(x[4])}));out.set(r.symbol,b)}return out}
function pair(a,b){const m=new Map(b.map(x=>[x.date,x.close]));const x=[];for(let i=1;i<a.length;i++){let p=m.get(a[i-1].date),q=m.get(a[i].date);if(p&&q)x.push([(a[i].close/a[i-1].close)-1,(q/p)-1])}if(x.length<20)return null;const ax=x.map(z=>z[0]),by=x.map(z=>z[1]),mean=z=>z.reduce((s,v)=>s+v,0)/z.length;let ma=mean(ax),mb=mean(by),cov=0,va=0,vb=0;for(let i=0;i<x.length;i++){cov+=(ax[i]-ma)*(by[i]-mb);va+=(ax[i]-ma)**2;vb+=(by[i]-mb)**2}const corr=cov/Math.sqrt(va*vb);return{correlation:corr,beta:cov/vb,r2:corr*corr,observations:x.length};}
function cmpReturns(b,n){return b.length>n?(b.at(-1).close/b.at(-(n+1)).close-1)*100:null}
