const fund=`${base}/fundamentals.json`, f=facet(fund,'financials'),s=facet(fund,'stats'),cal=facet(fund,'calendar'),sur=facet(fund,'earnings_surprises'), q=facet(fund,'earnings_quarterly')||[],tr=`${base}/technicals.json`,tech=qfacet(tr,'technicals');
