const xle=groups.flatMap(g=>g.symbols).find(x=>x.ticker==='XLE');const options=facet(`${base}/options.json`,'options_chain');const contracts=options.contracts||[];const call=contracts.filter(x=>x.option_type==='call').reduce((n,x)=>n+(x.open_interest||0),0),put=contracts.filter(x=>x.option_type==='put').reduce((n,x)=>n+(x.open_interest||0),0),iv=contracts.filter(x=>Number.isFinite(x.implied_vol));const avgIv=iv.length?iv.reduce((n,x)=>n+x.implied_vol,0)/iv.length:null;const maturity=contracts[0]?.expiry||null;
